import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"What is ntfy-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1787823347000}`),a={name:`guide/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-ntfy-mcp" tabindex="-1">What is ntfy-mcp? <a class="header-anchor" href="#what-is-ntfy-mcp" aria-label="Permalink to “What is ntfy-mcp?”">​</a></h1><p>An MCP server for <a href="https://ntfy.sh" target="_blank" rel="noreferrer">ntfy</a>, the pub-sub notification service that sends push messages to your phone with an HTTP request and nothing else.</p><p>It lets MCP clients like Claude Code, Claude Desktop or Codex send you notifications, read back what was sent, revise a notification in place while a job runs, and — with an admin account — create accounts and grant or revoke their access to topics, which otherwise means the <code>ntfy</code> command line on the server.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>A long-running task that finishes while nobody is watching is the case ntfy exists for, and it is exactly the case an assistant runs into. The interesting part is not the first message but the second: <code>publish_message</code> returns an id that is also the notification&#39;s sequence id, so <code>update_message</code> can revise the same notification rather than adding another one. A build that reports &quot;running&quot;, &quot;tests passed&quot; and &quot;deployed&quot; stays one entry on the phone.</p><p>The other half is administration. ntfy&#39;s authorization model — which account may read or write which topic — is otherwise reachable only through the <code>ntfy</code> command line on the server, and <code>list_users</code> answers &quot;who can read topic X&quot; from a client.</p><h2 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to “What it is not”">​</a></h2><ul><li><strong>A mail or telephone gateway.</strong> ntfy can turn a published message into an email or a phone call. Neither is exposed here: a tool that mails an arbitrary address on model output is a spam relay driven by injectable content, and <code>call</code> places a real, billable call.</li><li><strong>A way to obtain credentials.</strong> No tool creates, reads or exchanges an ntfy access token, because every such endpoint hands back a live credential that would then sit in the conversation transcript.</li><li><strong>A subscriber.</strong> <code>/sse</code>, <code>/ws</code> and <code>/raw</code> are streams; a tool call is request/response under a timeout. <code>list_messages</code> returns the same data, bounded.</li><li><strong>An upload endpoint.</strong> Attachments are attached by URL. The alternative is base64 through the model&#39;s context or a local filesystem this server has no business touching.</li></ul>`,8)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};